import{_ as t,c as a,o as s,ae as r}from"./chunks/framework.Cd-3tpCq.js";const l=JSON.parse('{"title":"Search Synonyms","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/search-seo/search-synonyms/index.md","filePath":"api/rest-api/admin/marketing/search-seo/search-synonyms/index.md"}'),n={name:"api/rest-api/admin/marketing/search-seo/search-synonyms/index.md"};function o(i,e,h,d,c,m){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="search-synonyms" tabindex="-1">Search Synonyms <a class="header-anchor" href="#search-synonyms" aria-label="Permalink to &quot;Search Synonyms&quot;">​</a></h1><p>A <strong>search synonym</strong> is a group of interchangeable search words. When a shopper searches for any word in the group, the storefront also matches products containing the other words — so a search for &quot;shirt&quot; still finds products tagged &quot;tshirt&quot; or &quot;tee&quot;. It mirrors the admin <strong>Marketing → Search &amp; SEO → Search Synonyms</strong> screen.</p><h2 id="how-search-synonyms-work" tabindex="-1">How search synonyms work <a class="header-anchor" href="#how-search-synonyms-work" aria-label="Permalink to &quot;How search synonyms work&quot;">​</a></h2><p>A synonym group widens storefront search recall by treating several words as equivalent.</p><ul><li><strong><code>name</code></strong> — a label for the group, used only to identify it in the admin list.</li><li><strong><code>terms</code></strong> — a comma-separated list of the interchangeable words (e.g. <code>shirt,tshirt,tee</code>). A search for any one of them matches products containing any of the others.</li></ul><p><strong>What it does for search.</strong> Without a synonym group, a search only matches the exact words typed. Grouping words together means a shopper who searches &quot;tee&quot; still sees every shirt, even if the product copy never uses the word &quot;tee&quot; — recovering sales that would otherwise return no results.</p><p><strong>Relation to other menus.</strong> <a href="/api/rest-api/admin/marketing/search-seo/search-terms/">Search Terms</a> reveal the words shoppers actually use and where the catalog returns too few results. Search Synonyms act on that signal — grouping the searched word with the words the catalog does use, so a low-result term starts matching the right products.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-list.html">List</a></td><td><code>GET /api/admin/marketing/search-synonyms</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/search-synonyms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-create.html">Create</a></td><td><code>POST /api/admin/marketing/search-synonyms</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-update.html">Update</a></td><td><code>PUT /api/admin/marketing/search-synonyms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/search-synonyms/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/search-seo/search-synonyms-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/search-synonyms/mass-delete</code></td></tr></tbody></table><p>All Search Synonyms endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',10)]))}const y=t(n,[["render",o]]);export{l as __pageData,y as default};
